package com.campusnova.service;
import com.campusnova.chatbot.IntentMatcher; import com.campusnova.dto.ChatRequest; import com.campusnova.model.*; import com.campusnova.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ChatbotService { private final FaqRepository faqs; private final ChatHistoryRepository history; private final IntentMatcher matcher; public ChatbotService(FaqRepository f,ChatHistoryRepository h,IntentMatcher m){faqs=f;history=h;matcher=m;}
 public Map<String,Object> respond(ChatRequest request){String clean=request.getQuestion().trim().toLowerCase(); Faq best=null; double bestScore=0; for(Faq f:faqs.findByActiveTrue()){double score=matcher.score(clean,f); if(score>bestScore){bestScore=score;best=f;}} boolean found=best!=null && bestScore>=.20; String answer=found?best.getAnswer():"I couldn't find a reliable answer for that yet. Try asking about admissions, fees, exams, library, courses, placements, or campus facilities."; String category=found?best.getCategory().getName():"General"; history.save(new ChatHistory(request.getSessionId()==null?"guest":request.getSessionId(),request.getQuestion(),answer,category,found)); Map<String,Object> result=new LinkedHashMap<String,Object>(); result.put("answer",answer);result.put("category",category);result.put("confidence",Math.round(bestScore*100));result.put("answered",found);result.put("suggestions",Arrays.asList("What are the library timings?","Tell me about placements","What documents are needed for admission?"));return result; }
}
